import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

function admin() {
  return createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!)
}

// Recompute and cache a listing's rating aggregate after a review changes.
async function refreshAggregate(supabase: ReturnType<typeof admin>, listingId: string) {
  const { data: rows } = await supabase
    .from('produce_reviews')
    .select('star_rating')
    .eq('produce_listing_id', listingId)
    .eq('approved', true)
  const count = rows?.length ?? 0
  const avg = count > 0
    ? Math.round((rows!.reduce((s, r: { star_rating: number }) => s + r.star_rating, 0) / count) * 10) / 10
    : null
  await supabase
    .from('produce_listings')
    .update({ rating_avg: avg, review_count: count })
    .eq('id', listingId)
}

// GET /api/produce-reviews?listing_id=<uuid>
// Public — returns approved reviews + aggregate for a produce listing.
export async function GET(req: NextRequest) {
  const listingId = new URL(req.url).searchParams.get('listing_id') ?? ''
  if (!UUID_RE.test(listingId)) {
    return NextResponse.json({ error: 'Invalid listing id.' }, { status: 400 })
  }

  const supabase = admin()
  const { data: reviews, error } = await supabase
    .from('produce_reviews')
    .select('id, reviewer_name, star_rating, review_text, created_at')
    .eq('produce_listing_id', listingId)
    .eq('approved', true)
    .order('created_at', { ascending: false })
    .limit(100)

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })

  const count = reviews?.length ?? 0
  const avg = count > 0
    ? Math.round((reviews!.reduce((s, r) => s + r.star_rating, 0) / count) * 10) / 10
    : null

  return NextResponse.json({ reviews: reviews ?? [], rating_avg: avg, review_count: count })
}

// POST /api/produce-reviews
// Verified buyer leaves a review on a produce they ordered, once the order is
// delivered / picked up. Body: { order_id, star_rating, review_text? }.
export async function POST(req: NextRequest) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Login required.' }, { status: 401 })

  let body: { order_id?: unknown; star_rating?: unknown; review_text?: unknown }
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid request.' }, { status: 400 })
  }

  const orderId = typeof body.order_id === 'string' ? body.order_id : ''
  if (!UUID_RE.test(orderId)) {
    return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })
  }
  const rating = typeof body.star_rating === 'number' ? body.star_rating : NaN
  if (!Number.isInteger(rating) || rating < 1 || rating > 5) {
    return NextResponse.json({ error: 'Rating must be 1-5.' }, { status: 400 })
  }
  const text = typeof body.review_text === 'string' ? body.review_text.trim().slice(0, 600) : ''

  const supabase = admin()

  const { data: order, error: orderErr } = await supabase
    .from('orders')
    .select('id, consumer_id, produce_listing_id, farmer_id, buyer_name, buyer_phone, status, received_at, collected_at, delivered_at, delivery_status')
    .eq('id', orderId)
    .maybeSingle()

  if (orderErr) return NextResponse.json({ error: orderErr.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.consumer_id !== session.consumerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }
  if (!order.produce_listing_id) {
    return NextResponse.json({ error: 'This order cannot be reviewed.' }, { status: 400 })
  }

  // A buyer may give feedback on any of their own orders. Only feedback on a
  // *completed* order (delivered / picked up / received) is published publicly
  // and counts toward the produce's star average — that's a verified-buyer
  // rating. Feedback on a declined / cancelled / still-pending order is private
  // (approved = false): it's the buyer telling us about their experience, and is
  // never shown on the produce card so it can't unfairly drag the rating down.
  const completed =
    order.status !== 'declined' &&
    order.status !== 'cancelled' &&
    (!!order.received_at || !!order.collected_at || !!order.delivered_at || order.delivery_status === 'delivered')

  // One review per order.
  const { data: existing } = await supabase
    .from('produce_reviews')
    .select('id')
    .eq('order_id', orderId)
    .maybeSingle()
  if (existing) {
    return NextResponse.json({ error: 'already_reviewed' }, { status: 409 })
  }

  const { data: review, error: insErr } = await supabase
    .from('produce_reviews')
    .insert({
      order_id: orderId,
      produce_listing_id: order.produce_listing_id,
      farmer_id: order.farmer_id ?? null,
      consumer_id: order.consumer_id ?? null,
      reviewer_name: (order.buyer_name as string | null)?.trim()?.slice(0, 80) || 'Buyer',
      reviewer_phone: order.buyer_phone ? String(order.buyer_phone).replace(/\D/g, '').slice(-10) : null,
      star_rating: rating,
      review_text: text || null,
      approved: completed,
    })
    .select('id, reviewer_name, star_rating, review_text, created_at')
    .single()

  if (insErr) return NextResponse.json({ error: insErr.message }, { status: 500 })

  // Private (non-completed) feedback never affects the public average, so only
  // recompute the aggregate when a completed order added a public rating.
  if (completed) await refreshAggregate(supabase, order.produce_listing_id)

  return NextResponse.json({ review })
}

'use client'

import { useState } from 'react'
import { useLang } from '@/lib/LanguageContext'
import { localizeName } from '@/lib/localizeName'
import type { MyReview } from '@/components/consumer/ProduceReviewBox'

// Shared feedback sheet, opened from an order card. A buyer can rate the produce
// for any of their orders. For a completed order it's a public verified-buyer
// rating; for a declined / cancelled / pending order it's private feedback about
// the order experience (kept off the public produce card).
export default function OrderFeedbackModal({
  orderId,
  produceName,
  completed,
  existing,
  onClose,
  onSaved,
}: {
  orderId: string
  produceName: string | null
  completed: boolean
  existing: MyReview | null
  onClose: () => void
  onSaved: () => void
}) {
  const { L, lang } = useLang()
  const name = localizeName(produceName, lang) || L('this produce', 'ఈ ఉత్పత్తి')
  const [rating, setRating] = useState(existing?.star_rating ?? 0)
  const [hover, setHover] = useState(0)
  const [text, setText] = useState(existing?.review_text ?? '')
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState('')
  const readOnly = Boolean(existing)

  const submit = async () => {
    if (rating === 0) { setError(L('Please tap a star to rate.', 'రేటింగ్ కోసం స్టార్ నొక్కండి.')); return }
    setSubmitting(true)
    setError('')
    const res = await fetch('/api/produce-reviews', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({ order_id: orderId, star_rating: rating, review_text: text.trim() || null }),
    }).catch(() => null)
    const json = await res?.json().catch(() => ({})) as { review?: MyReview; error?: string }
    setSubmitting(false)
    if (!res || !res.ok || !json.review) {
      setError(json?.error === 'already_reviewed'
        ? L('You already gave feedback on this order.', 'మీరు ఇప్పటికే ఈ ఆర్డర్‌పై అభిప్రాయం ఇచ్చారు.')
        : (json?.error ?? L('Could not submit. Try again.', 'సమర్పించలేకపోయాం. మళ్ళీ ప్రయత్నించండి.')))
      return
    }
    onSaved()
  }

  return (
    <div className="fixed inset-0 z-50 bg-black/40 flex items-end sm:items-center justify-center p-4" onClick={onClose}>
      <div className="bg-white rounded-2xl w-full max-w-md p-5" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-1">
          <p className="font-extrabold text-gray-900">
            {readOnly
              ? L('Your feedback', 'మీ అభిప్రాయం')
              : completed
                ? `${L('Rate', 'రేటింగ్')} ${name}`
                : L('Give feedback', 'అభిప్రాయం ఇవ్వండి')}
          </p>
          <button onClick={onClose} className="text-gray-400 text-2xl leading-none p-1">×</button>
        </div>

        <p className="text-[11px] text-gray-500 mb-3">
          {readOnly
            ? L('Thanks for helping other buyers!', 'ఇతర కొనుగోలుదారులకు సహాయం చేసినందుకు ధన్యవాదాలు!')
            : completed
              ? L('How was it? Your review helps other buyers.', 'ఎలా ఉంది? మీ సమీక్ష ఇతర కొనుగోలుదారులకు సహాయపడుతుంది.')
              : L('Tell us about this order. This stays private and helps us improve.', 'ఈ ఆర్డర్ గురించి చెప్పండి. ఇది గోప్యంగా ఉంటుంది & మేము మెరుగుపడటానికి సహాయపడుతుంది.')}
        </p>

        <div className="flex gap-1 mb-3">
          {[1, 2, 3, 4, 5].map((s) => (
            <button
              key={s}
              type="button"
              disabled={readOnly}
              onClick={() => setRating(s)}
              onMouseEnter={() => !readOnly && setHover(s)}
              onMouseLeave={() => !readOnly && setHover(0)}
              className="text-4xl leading-none transition-transform active:scale-110 disabled:active:scale-100"
              aria-label={`${s} stars`}
            >
              <span className={(hover || rating) >= s ? 'text-yellow-400' : 'text-gray-200'}>★</span>
            </button>
          ))}
        </div>

        {readOnly ? (
          existing?.review_text && (
            <p className="text-sm text-gray-700 bg-gray-50 rounded-xl px-4 py-3 leading-relaxed">{existing.review_text}</p>
          )
        ) : (
          <textarea
            value={text}
            onChange={(e) => setText(e.target.value.slice(0, 600))}
            placeholder={L('Share a few words (optional)', 'కొన్ని మాటలు రాయండి (ఐచ్ఛికం)')}
            rows={3}
            className="w-full border border-gray-200 rounded-xl px-4 py-3 text-sm resize-none focus:border-green-500 focus:outline-none"
          />
        )}

        {error && <p className="text-sm text-red-600 bg-red-50 rounded-xl px-3 py-2 mt-2">{error}</p>}

        {!readOnly && (
          <button
            type="button"
            onClick={submit}
            disabled={submitting}
            className="mt-3 w-full bg-green-700 text-white font-bold py-3 rounded-xl text-sm disabled:opacity-50 active:bg-green-800"
          >
            {submitting ? L('Submitting…', 'సమర్పిస్తోంది…') : L('Submit feedback', 'అభిప్రాయం సమర్పించు')}
          </button>
        )}
      </div>
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useLang } from '@/lib/LanguageContext'

type Review = {
  id: string
  reviewer_name: string
  star_rating: number
  review_text: string | null
  created_at: string
}

// Bottom-sheet listing all buyer reviews for a produce. Opened from a produce
// card's rating chip. Reviews come from GET /api/produce-reviews.
export default function ProduceReviewsModal({
  listingId,
  produceName,
  onClose,
}: {
  listingId: string
  produceName: string
  onClose: () => void
}) {
  const { L } = useLang()
  const [reviews, setReviews] = useState<Review[]>([])
  const [avg, setAvg] = useState<number | null>(null)
  const [count, setCount] = useState(0)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    let alive = true
    fetch(`/api/produce-reviews?listing_id=${listingId}`)
      .then((r) => r.json())
      .then((j) => {
        if (!alive) return
        setReviews((j.reviews ?? []) as Review[])
        setAvg(j.rating_avg ?? null)
        setCount(j.review_count ?? 0)
      })
      .catch(() => {})
      .finally(() => { if (alive) setLoading(false) })
    return () => { alive = false }
  }, [listingId])

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-end sm:items-center justify-center p-0 sm:p-4" onClick={onClose}>
      <div
        className="bg-white rounded-t-2xl sm:rounded-2xl w-full max-w-md max-h-[85vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="sticky top-0 bg-white flex items-center justify-between px-4 py-3 border-b border-gray-100">
          <div className="min-w-0">
            <h3 className="font-extrabold text-gray-900 text-base truncate">{produceName}</h3>
            <p className="text-xs text-gray-500">{L('Buyer reviews', 'కొనుగోలుదారుల సమీక్షలు')}</p>
          </div>
          <button onClick={onClose} className="text-gray-400 text-3xl leading-none p-1">×</button>
        </div>

        <div className="p-4 space-y-3">
          {avg != null && count > 0 && (
            <div className="flex items-center gap-3 bg-green-50 border border-green-100 rounded-xl px-4 py-3">
              <p className="text-3xl font-extrabold text-gray-900">{avg.toFixed(1)}</p>
              <div>
                <div className="flex">
                  {[1, 2, 3, 4, 5].map((s) => (
                    <span key={s} className={`text-base ${s <= Math.round(avg) ? 'text-yellow-400' : 'text-gray-200'}`}>★</span>
                  ))}
                </div>
                <p className="text-xs text-gray-500 mt-0.5">
                  {count} {count === 1 ? L('review', 'సమీక్ష') : L('reviews', 'సమీక్షలు')}
                </p>
              </div>
            </div>
          )}

          {loading ? (
            <p className="text-center text-sm text-gray-400 py-8">{L('Loading…', 'లోడ్ అవుతోంది…')}</p>
          ) : reviews.length === 0 ? (
            <p className="text-center text-sm text-gray-400 py-8">{L('No reviews yet.', 'ఇంకా సమీక్షలు లేవు.')}</p>
          ) : (
            reviews.map((r) => (
              <div key={r.id} className="bg-white border border-gray-100 rounded-xl p-3">
                <div className="flex items-start justify-between gap-2">
                  <div className="flex items-center gap-2 min-w-0">
                    <div className="w-8 h-8 rounded-full bg-green-100 flex items-center justify-center text-green-800 font-bold text-xs flex-shrink-0">
                      {r.reviewer_name.slice(0, 2).toUpperCase()}
                    </div>
                    <p className="text-sm font-semibold text-gray-900 truncate">{r.reviewer_name}</p>
                  </div>
                  <div className="flex flex-shrink-0">
                    {[1, 2, 3, 4, 5].map((s) => (
                      <span key={s} className={`text-sm ${s <= r.star_rating ? 'text-yellow-400' : 'text-gray-200'}`}>★</span>
                    ))}
                  </div>
                </div>
                {r.review_text && <p className="text-sm text-gray-600 mt-2 leading-relaxed">{r.review_text}</p>}
                <p className="text-[10px] text-gray-400 mt-1.5">
                  {new Date(r.created_at).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}
                </p>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  )
}

'use client'

import Link from 'next/link'
import { useLang } from '@/lib/LanguageContext'
import { localizeName } from '@/lib/localizeName'
import type { MyReview } from '@/components/consumer/ProduceReviewBox'

type DeliveryStatus = 'unassigned' | 'assigned' | 'picked_up' | 'out_for_delivery' | 'delivered'

export type ConsumerOrder = {
  id: string
  order_code: string | null
  produce_name: string | null
  produce_listing_id?: string | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  pickup_location: string | null
  status: 'pending' | 'approved' | 'declined' | 'cancelled'
  payment_method: string | null
  payment_status: string | null
  refund_status: string | null
  decline_reason: string | null
  payment_proof_path: string | null
  created_at: string
  farmer_id: string
  farmer?: {
    name: string
    slug: string
    village: string
    phone: string | null
    upi_id: string | null
  } | null
  delivery_type?: 'self_pickup' | 'home_delivery' | 'courier' | null
  delivery_status?: DeliveryStatus | null
  shipped_at?: string | null
  collected_at?: string | null
  received_at?: string | null
  delivered_at?: string | null
  // When the buyer acknowledged a declined/cancelled order (moves it to history).
  acknowledged_at?: string | null
  // The buyer's own feedback for this order, if they've left any.
  my_review?: MyReview | null
}

// A completed order — delivered / picked up / received, and not declined or
// cancelled. Feedback on these is published as a public produce rating; feedback
// on any other order is kept private. Mirrors the gate in /api/produce-reviews.
export const isCompleted = (o: ConsumerOrder) =>
  o.status !== 'declined'
  && o.status !== 'cancelled'
  && (o.delivery_status === 'delivered' || !!o.collected_at || !!o.received_at || !!o.delivered_at)

// An order is "resolved" once it reaches a terminal state: delivered (home
// delivery), picked up (self-pickup) or received (courier). A declined/cancelled
// order is only resolved once the buyer has acknowledged it — until then it
// stays in the Active list with an Acknowledge button so a farmer decline/cancel
// never silently drops into history. Active = everything else still in progress.
// Shared so the active list and the history page agree on where each order belongs.
export const isResolved = (o: ConsumerOrder) =>
  ((o.status === 'declined' || o.status === 'cancelled') && !!o.acknowledged_at)
  || o.delivery_status === 'delivered'
  || !!o.collected_at
  || !!o.received_at

// A declined/cancelled order still waiting on the buyer's acknowledgement.
// Shown in the Active list with an Acknowledge button.
export const needsAcknowledge = (o: ConsumerOrder) =>
  (o.status === 'declined' || o.status === 'cancelled') && !o.acknowledged_at

export default function OrderCard({
  order,
  onComplaint,
  onFeedback,
  onAcknowledge,
  onConfirmReceipt,
  busy = false,
}: {
  order: ConsumerOrder
  onComplaint: (orderCode: string) => void
  onFeedback?: (order: ConsumerOrder) => void
  // Acknowledge a declined/cancelled order (moves it to history).
  onAcknowledge?: (order: ConsumerOrder) => void
  // Confirm a shipped order was delivered/received.
  onConfirmReceipt?: (order: ConsumerOrder) => void
  // The parent is mid-request for this card (disables the action buttons).
  busy?: boolean
}) {
  const { tx, lang, L } = useLang()
  const reviewed = Boolean(order.my_review)
  const completed = isCompleted(order)
  const awaitingAck = needsAcknowledge(order)
  // A shipped order (courier or farmer-shipped home delivery) the buyer can
  // confirm. Rider deliveries never set shipped_at, self-pickup is excluded.
  const canConfirmReceipt = Boolean(
    onConfirmReceipt
      && order.delivery_type !== 'self_pickup'
      && order.shipped_at
      && !order.received_at
      && order.status !== 'cancelled'
      && order.status !== 'declined',
  )
  // Feedback is only offered once the order is completed (delivered / picked up
  // / received). Showing it on a pending order is meaningless — the buyer hasn't
  // received the produce yet. Already-reviewed orders keep the button so the
  // buyer can see / edit what they left.
  const canFeedback = Boolean(onFeedback && order.produce_listing_id && (completed || reviewed))

  const statusColor = (s: string) =>
    s === 'approved'
      ? 'bg-green-100 text-green-800'
      : s === 'declined'
        ? 'bg-red-100 text-red-700'
        : s === 'cancelled'
          ? 'bg-gray-200 text-gray-700'
          : 'bg-amber-100 text-amber-800'

  const deliveryStatusLabel = (s: DeliveryStatus | null | undefined) => {
    switch (s) {
      case 'assigned': return L('Rider assigned', 'రైడర్ కేటాయించబడ్డారు')
      case 'picked_up': return L('Picked up', 'తీసుకున్నారు')
      case 'out_for_delivery': return L('Out for delivery', 'డెలివరీకి బయలుదేరారు')
      case 'delivered': return L('Delivered', 'డెలివరీ అయింది')
      default: return L('Waiting for rider', 'రైడర్ కోసం వేచి ఉంది')
    }
  }

  // Home-delivery status line. With a rider assigned it's the rider flow; with
  // no rider it's farmer-shipped, so we show the Shipped → Received progress.
  const homeDeliveryLabel = () => {
    const ds = order.delivery_status
    const riderAssigned = ds != null && ds !== 'unassigned'
    if (riderAssigned) return deliveryStatusLabel(ds)
    if (order.received_at) return L('Delivered', 'డెలివరీ అయింది')
    if (order.shipped_at) return L('On the way', 'దారిలో ఉంది')
    return L('Preparing your order', 'ఆర్డర్ సిద్ధం చేస్తున్నారు')
  }

  const statusLabel = (s: string) =>
    s === 'approved' ? tx.statusConfirmed
      : s === 'declined' ? tx.statusDeclined
      : s === 'cancelled' ? tx.statusCancelled
      : tx.statusPending

  const paymentBadge = () => {
    if (!order.payment_method || order.payment_method === 'cod') return null
    // Online payments now go through Razorpay.
    if (order.payment_method === 'razorpay' && order.payment_status === 'paid') {
      return { label: L('✓ Paid online', 'ఆన్‌లైన్ చెల్లించారు'), cls: 'bg-green-100 text-green-800' }
    }
    // Manual UPI is retired — legacy UPI orders show no pay prompt.
    return null
  }

  const badge = paymentBadge()

  return (
    <Link href={`/consumer/orders/${order.id}`} className="block">
      <div className="bg-white rounded-2xl border border-gray-100 overflow-hidden active:bg-gray-50">
        <div className="p-4 space-y-2">
          <div className="flex items-start justify-between gap-2">
            <div className="min-w-0">
              <p className="font-extrabold text-gray-900 text-sm leading-tight">
                {localizeName(order.produce_name, lang) || '—'}
              </p>
              {order.order_code && (
